Hungary.","alternatives":[{"id":"01a218f9-36fb-7601-9a21-6a508d8b7e6d","description":"St. Stephen","correct_answer":true},{"id":"01a218f9-36fb-7f1b-a896-27a6c020e292","description":"St. Marko","correct_answer":false},{"id":"01a218f9-36fb-71e7-8224-7e3203632533","description":"St. Cyril","correct_answer":false},{"id":"01a218f9-36fb-76ec-b8fd-c628f073d6bb","description":"St. Alexander","correct_answer":false}]},{"id":"01a218f9-36fb-78c7-bf9a-c33cf36b0dbe","locale":"en-US","category":"01a21312-b489-7ebc-94f2-41649ebfcaca","question":"About how long did the American Civil War last?","difficulty":3,"explanation":"The American Civil War lasted about four years, from 1861 to 1865. General Robert E. Lee\'s surrender at Appomattox in April 1865 marked a key turning point toward its end.","alternatives":[{"id":"01a218f9-36fb-7804-a02f-c80fffa609ee","description":"Four years","correct_answer":true},{"id":"01a218f9-36fb-7e99-b5e9-b53c7e56760c","description":"One year","correct_answer":false},{"id":"01a218f9-36fb-7141-99b2-38b974ccef79","description":"Seven years","correct_answer":false},{"id":"01a218f9-36fb-7923-8eb5-30c43f0b179f","description":"Ten years","correct_answer":false}]},{"id":"01a218f9-36fb-71e8-b67b-9c15802e2753","locale":"en-US","category":"01a21312-b489-7ebc-94f2-41649ebfcaca","question":"In which battle was George A. Custer defeated?","difficulty":3,"explanation":"At the Battle of Little Bighorn, Lakota, Cheyenne, and Arapaho warriors overwhelmed Custer\'s forces.","alternatives":[{"id":"01a218f9-36fb-708a-bbba-5f856e74b091","description":"Battle of Little Bighorn","correct_answer":true},{"id":"01a218f9-36fb-747f-bb2e-0f1124b1a9c9","description":"Battle of Gettysburg","correct_answer":false},{"id":"01a218f9-36fb-71e3-aff9-0dda765794ea","description":"Battle of Cold Harbor","correct_answer":false},{"id":"01a218f9-36fb-7647-b991-064636715d34","description":"Battle of Stones River","correct_answer":false}]},{"id":"01a218f9-36fb-781e-a405-be705048f20e","locale":"en-US","category":"01a21312-b489-7ebc-94f2-41649ebfcaca","question":"Who was the great czar who led Russia to victory against Charles XII of Sweden in The Great Northern War of 1700-1721?","difficulty":3,"explanation":"Peter the Great\u2019s victory over Charles XII at the Battle of Poltava in 1709 was a turning point in the war.","alternatives":[{"id":"01a218f9-36fb-75ba-be6b-32a88f1b4d1c","description":"Peter The Great","correct_answer":true},{"id":"01a218f9-36fb-73f7-8166-56bd06188e13","description":"Ivan The Terrible","correct_answer":false},{"id":"01a218f9-36fb-74d0-b092-4712f8a9e308","description":"Catherine The Great","correct_answer":false},{"id":"01a218f9-36fb-767a-af93-59733d84cb30","description":"Ivan The Great","correct_answer":false}]},{"id":"01a218f9-36fb-71b0-87e1-2f22ff029fd9","locale":"en-US","category":"01a21312-b489-7ebc-94f2-41649ebfcaca","question":"Which wine god\'s orgiastic worship was suppressed by the Roman Senate in the 180s BC?","difficulty":3,"explanation":"Bacchus was the Roman counterpart of the Greek god Dionysus. The Senate restricted the secret rites, though worship continued under tighter controls.","alternatives":[{"id":"01a218f9-36fb-7570-8d9f-94200b2f93de","description":"Bacchus","correct_answer":true},{"id":"01a218f9-36fb-7020-ba57-d46521e16b91","description":"Apollo","correct_answer":false},{"id":"01a218f9-36fb-74d5-b96c-a964f1103781","description":"Zeus","correct_answer":false},{"id":"01a218f9-36fb-7373-b158-6e2041b64525","description":"Hermes","correct_answer":false}]},{"id":"01a218f9-36fb-7e43-a998-6c7de2a2a160","locale":"en-US","category":"01a21312-b489-7ebc-94f2-41649ebfcaca","question":"What was the name of the vehicle in which Sir Malcom Campbell broke the 300mph barrier in 1935?","difficulty":3,"explanation":"Blue Bird reached 301.129 mph on Utah\'s Bonneville Salt Flats, making Campbell the first person to exceed 300 mph in a land vehicle.","alternatives":[{"id":"01a218f9-36fb-7681-8ef1-35383846341c","description":"Blueb